-- M1: closet items, their photos, and an AI usage ledger.
-- Follows the pattern in 20261110000000_profiles.sql: RLS on, policies scoped
-- to (select auth.uid()), explicit minimal grants, nothing for anon.

------------------------------------------------------------------------------
-- Items
------------------------------------------------------------------------------

create type public.item_status as enum ('active', 'laundry', 'archived');
create type public.item_tag_status as enum ('pending', 'done', 'failed', 'not_clothing');

create table public.items (
  -- Generated by the browser so photos can be uploaded to their final path
  -- before the row exists.
  id uuid primary key,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  image_path text not null,
  thumb_path text not null,
  status public.item_status not null default 'active',
  tag_status public.item_tag_status not null default 'pending',
  tagged_at timestamptz,

  category text check (
    category in ('top', 'bottom', 'dress', 'outerwear', 'shoes', 'bag', 'accessory', 'activewear', 'other')
  ),
  subcategory text check (char_length(subcategory) <= 60),
  colors text[] not null default '{}' check (cardinality(colors) <= 4),
  pattern text check (char_length(pattern) <= 30),
  material text check (char_length(material) <= 60),
  formality smallint check (formality between 1 and 5),
  warmth smallint check (warmth between 1 and 5),
  seasons text[] not null default '{}'
    check (seasons <@ array['spring', 'summer', 'autumn', 'winter']),
  style_tags text[] not null default '{}' check (cardinality(style_tags) <= 8),
  description text check (char_length(description) <= 120),
  brand text check (char_length(brand) <= 60),

  wear_count integer not null default 0 check (wear_count >= 0),
  last_worn_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  -- A row can only point at photos in its owner's own folder.
  constraint items_paths_in_owner_folder check (
    image_path = user_id::text || '/' || id::text || '/full.jpg'
    and thumb_path = user_id::text || '/' || id::text || '/thumb.jpg'
  )
);

create index items_user_created_idx on public.items (user_id, created_at desc);

alter table public.items enable row level security;

create policy "Users can read their own items"
  on public.items for select to authenticated
  using ((select auth.uid()) = user_id);

create policy "Users can add their own items"
  on public.items for insert to authenticated
  with check ((select auth.uid()) = user_id);

create policy "Users can update their own items"
  on public.items for update to authenticated
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);

create policy "Users can delete their own items"
  on public.items for delete to authenticated
  using ((select auth.uid()) = user_id);

-- Users never set user_id (it defaults to auth.uid()) or wear stats (M4 will
-- update those through a function).
revoke all on public.items from anon, authenticated;
grant select, delete on public.items to authenticated;
grant insert (id, image_path, thumb_path) on public.items to authenticated;
grant update (
  status, tag_status, tagged_at, category, subcategory, colors, pattern, material,
  formality, warmth, seasons, style_tags, description, brand
) on public.items to authenticated;

create trigger items_set_updated_at
  before update on public.items
  for each row execute function public.set_updated_at();

------------------------------------------------------------------------------
-- AI usage ledger + daily quota
------------------------------------------------------------------------------

-- One row per paid AI call. Users can read their own history but can't write
-- to it: rows are only added by consume_ai_quota(), so the cap can't be bypassed.
create table public.ai_usage (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  kind text not null check (char_length(kind) <= 40),
  created_at timestamptz not null default now()
);

create index ai_usage_user_kind_created_idx on public.ai_usage (user_id, kind, created_at desc);

alter table public.ai_usage enable row level security;

create policy "Users can read their own AI usage"
  on public.ai_usage for select to authenticated
  using ((select auth.uid()) = user_id);

revoke all on public.ai_usage from anon, authenticated;
grant select on public.ai_usage to authenticated;

-- Records one call of `p_kind` for the current user if they're under
-- `p_daily_limit` calls in the last 24 hours. Returns false when over the limit.
create function public.consume_ai_quota(p_kind text, p_daily_limit integer)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_count integer;
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  -- Serialize per user so parallel requests can't both slip under the limit.
  perform pg_advisory_xact_lock(hashtextextended(v_user::text, 0));

  select count(*) into v_count
  from public.ai_usage
  where user_id = v_user
    and kind = p_kind
    and created_at > now() - interval '1 day';

  if v_count >= p_daily_limit then
    return false;
  end if;

  insert into public.ai_usage (user_id, kind) values (v_user, p_kind);
  return true;
end;
$$;

revoke execute on function public.consume_ai_quota(text, integer) from public, anon;
grant execute on function public.consume_ai_quota(text, integer) to authenticated;

------------------------------------------------------------------------------
-- Photo storage
------------------------------------------------------------------------------

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('closet', 'closet', false, 10485760, array['image/jpeg'])
on conflict (id) do nothing;

-- Paths are {user_id}/{item_id}/full.jpg and .../thumb.jpg: users may only
-- touch objects inside their own top-level folder.
create policy "closet: users read their own photos"
  on storage.objects for select to authenticated
  using (bucket_id = 'closet' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "closet: users upload to their own folder"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'closet' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "closet: users replace their own photos"
  on storage.objects for update to authenticated
  using (bucket_id = 'closet' and (storage.foldername(name))[1] = (select auth.uid())::text)
  with check (bucket_id = 'closet' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "closet: users delete their own photos"
  on storage.objects for delete to authenticated
  using (bucket_id = 'closet' and (storage.foldername(name))[1] = (select auth.uid())::text);
